type brainBriefRawHistoryEndToEndFixture struct {
	opts Options
	task string
}

func newBrainBriefRawHistoryEndToEndFixture(tb testing.TB) brainBriefRawHistoryEndToEndFixture {
	tb.Helper()
	repoDir := tb.TempDir()
	env := EntireEnv{
		RepoRoot:        repoDir,
		PluginConfigDir: tb.TempDir(),
