	storage, err := repoStoragePaths(context.Background(), runner, env, repoDir)
	if err != nil {
		tb.Fatalf("storage: %v", err)
	}
	writeBrainBriefRawHistoryEndToEndCorpus(tb, storage.BrainDir)
