}

func newBrainBriefRawHistoryEndToEndFixture(tb testing.TB) brainBriefRawHistoryEndToEndFixture {
	tb.Helper()
	repoDir := tb.TempDir()
	env := EntireEnv{
		RepoRoot:        repoDir,
		PluginConfigDir: tb.TempDir(),
		PluginDataDir:   tb.TempDir(),
		PluginStateDir:  tb.TempDir(),
		PluginCacheDir:  tb.TempDir(),
	}
